import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        if isinstance(json_data, str):
            data = json.loads(json_data)
        else:
            data = json_data
    except Exception:
        raise ValueError("Malformed JSON data")

    if not data:
        raise ValueError("Empty JSON data")

    countries = []
    populations = []

    for item in data:
        c = item.get('Country', item.get('country'))
        p = item.get('Population', item.get('population'))
        if not isinstance(c, str):
            raise ValueError("Non-string country name")
        if not isinstance(p, (int, float)):
            raise ValueError("Non-numeric population")
        if p < 0:
            raise ValueError("Negative population")
        countries.append(c)
        populations.append(math.floor(p))

    df = pd.DataFrame({"Country": countries, "Population": populations})
    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except Exception:
        raise IOError("Cannot write to directory")

    return file_path, df

